cat > rewards/dense_tail.py <<'PY'
import math
def _g(r, k, d=None):
    return r.get(k, d) if isinstance(r, dict) else getattr(r, k, d)

def _prox(r):
    # Continuous placement credit: closeness of red cube to its rest-on-green position.
    fs = _g(r, "final_state", {}) or {}
    try:
        objs = fs.get("objects", {}) or {}
        red = objs.get("red_cube"); green = objs.get("green_cube")
        if not (red and green):
            return 0.0
        rp = list(red["pos"]); gp = list(green["pos"])
        rsz = list(red.get("size") or [0.04, 0.04, 0.04]); gsz = list(green.get("size") or [0.04, 0.04, 0.04])
        tz = gp[2] + gsz[2] / 2.0 + rsz[2] / 2.0
        d = math.sqrt((rp[0]-gp[0])**2 + (rp[1]-gp[1])**2 + (rp[2]-tz)**2)
        return max(0.0, 1.0 - d / 0.06)
    except Exception:
        return 0.0

def reward(r):
    st = _g(r, "stages", {}) or {}
    if not isinstance(st, dict):
        st = {}
    aligned = 1.0 if st.get("align the red over the green") else 0.0
    done = 1.0 if _g(r, "task_completed", False) else 0.0
    return 0.4 * _prox(r) + 0.25 * aligned + 0.35 * done
